/* fopen(3) demonstration: Opening a file for writing and checking errors */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main() {
    FILE *fp;
    const char *filename = "example_file.txt";
    const char *data = "This line was written using fopen.\n";

    // Attempt to open the file in write mode ("w")
    fp = fopen(filename, "w");

    if (fp == NULL) {
        // Error check: If fopen returns NULL, check errno
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return EXIT_FAILURE;
    }

    // Write data to the stream
    if (fputs(data, fp) == EOF) {
        fprintf(stderr, "Error writing data to file.\n");
        // Attempt to close the file even on write failure
        fclose(fp);
        return EXIT_FAILURE;
    }

    printf("Data successfully written to %s.\n", filename);

    // Close the stream, ensuring buffers are flushed
    if (fclose(fp) == EOF) {
        perror("fclose failed");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
